		err = nft_chain_parse_hook(ctx->net, basechain, nla, NULL,
					   ctx->family, 0, extack);
		if (err < 0)
			return err;
	}

	list_for_each_entry_safe(h, next, &basechain->hook_list, list) {
		if (h->ops.pf != ctx->family ||
		    h->ops.hooknum != basechain->ops.hooknum)
			continue;

		if (nla[NFTA_CHAIN_HOOK]) {
			if (h->ops.priority != basechain->ops.priority ||
			    h->ops.priv != basechain->ops.priv ||
			    h->ops.hook != basechain->ops.hook)
				continue;
		}

		err = nf_unregister_net_hook(ctx->net, &h->ops);
		if (err < 0) {
			NL_SET_ERR_MSG(extack, "Failed to unregister net hook");
			return err;
		}

		list_del(&h->list);
		kfree(h);
	}

	if (nla[NFTA_CHAIN_HOOK]) {
		err = nft_chain_parse_hook(ctx->net, basechain, nla, NULL,
					   ctx->family, 0, extack);
		if (err < 0)
			return err;
	}

	if (nla[NFTA_CHAIN_HOOK] &&
	    !nft_chain_has_hooks(chain))
		return -EOPNOTSUPP;

	return 0;
}
