static void ovl_kill_sb(struct super_block *sb)
{
	struct ovl_fs *ufs = sb->s_fs_info;
	unsigned int i;

	for (i = 0; i < ufs->numlower; i++)
		mntput(ufs->lower_mnt[i]);
	kfree(ufs->lower_mnt);
	dput(ufs->workdir);
	mntput(ufs->upper_mnt);
	for (i = 0; i < ufs->numlower; i++)
		path_put(&ufs->lowerstack[i]);
	kfree(ufs);
	kill_litter_super(sb);
}
