static int ovl_statfs(struct dentry *dentry, struct kstatfs *buf)
{
	struct super_block *sb = dentry->d_sb;
	struct ovl_fs *ufs = sb->s_fs_info;
	struct kstatfs ustat, wstat;
	int err;

	if (ufs->config.upperdir) {
		err = vfs_statfs(ufs->upper_mnt, &ustat);
		if (err)
			return err;
	} else {
		memset(&ustat, 0, sizeof(ustat));
	}

	err = vfs_statfs(ufs->lower_mnt[0], &wstat);
	if (err)
		return err;

	buf->f_type = ufs->sb->s_magic;
	buf->f_bsize = ustat.f_bsize;
	buf->f_blocks = ustat.f_blocks + wstat.f_blocks;
	buf->f_bfree = ustat.f_bfree + wstat.f_bfree;
	buf->f_bavail = ustat.f_bavail + wstat.f_bavail;
	buf->f_files = ustat.f_files + wstat.f_files;
	buf->f_ffree = ustat.f_ffree + wstat.f_ffree;
	buf->f_namelen = ustat.f_namelen;
	buf->f_fsid = ustat.f_fsid;
	buf->f_spare = ustat.f_spare;

	return 0;
}
